from pathlib import Path
from typing import Union, Dict, Any

def file_tree(directory: Union[str, Path], max_depth: int = 32) -> Dict[str, Any]:
    """Return a nested dict representation of a directory tree.

    Args:
        directory: Root directory.
        max_depth: Maximum recursion depth; -1 disables the cap.

    Returns:
        A dict with keys '__files__' (list of files) and per-subdir entries.

    Examples:
        >>> isinstance(file_tree("."), dict)
        True
    """
    root = Path(directory)
    if not root.is_dir():
        raise NotADirectoryError(str(root))

    def build(p: Path, depth: int) -> Dict[str, Any]:
        node: Dict[str, Any] = {"__files__": []}
        try:
            entries = sorted(p.iterdir(), key=lambda e: e.name)
        except OSError:
            return node
        for entry in entries:
            if entry.is_file():
                node["__files__"].append({
                    "name": entry.name,
                    "size": entry.stat().st_size,
                })
            elif entry.is_dir() and (max_depth < 0 or depth < max_depth):
                node[entry.name] = build(entry, depth + 1)
        return node

    return {root.name: build(root, 0)}

import json
import os
from pathlib import Path
from typing import Union, Any, Callable, Dict

def update_json(path: Union[str, Path], transformer: Callable[[Dict[str, Any]], Dict[str, Any]],
                default: Dict[str, Any] = None) -> Dict[str, Any]:
    """Atomically rewrite a JSON file with a transformer applied to its contents.

    Args:
        path: JSON file path.
        transformer: Function that maps the current dict to the new dict.
        default: Optional default used when the file is missing or unparseable.

    Returns:
        The new dict value that was written to disk.

    Examples:
        >>> update_json("nope.json", lambda d: {}, default={}) == {}
        True
    """
    p = Path(path)
    base: Dict[str, Any] = {}
    if p.exists():
        try:
            loaded = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                base = loaded
        except (json.JSONDecodeError, OSError):
            base = dict(default) if isinstance(default, dict) else {}
    elif default is not None and isinstance(default, dict):
        base = dict(default)
    new_data = transformer(dict(base))
    if p.parent and not p.parent.exists():
        p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_name(p.name + ".tmp")
    try:
        tmp.write_text(json.dumps(new_data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        os.replace(tmp, p)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass
    return new_data


def get_json_value(path: Union[str, Path], key: str, default: Any = None) -> Any:
    """Return a single key from a JSON object file, with a fallback.

    Args:
        path: JSON file path.
        key: Key to look up.
        default: Value returned when the key or file is absent.

    Returns:
        The decoded value or default.

    Examples:
        >>> get_json_value("missing.json", "k", default=1)
        1
    """
    p = Path(path)
    if not p.exists():
        return default
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return default
    if isinstance(data, dict):
        return data.get(key, default)
    return default

from pathlib import Path
from typing import Union, Dict, Any

def _coerce(text: str) -> Any:
    stripped = text.strip()
    if not stripped:
        return ""
    lowered = stripped.lower()
    if lowered in ("true", "false"):
        return lowered == "true"
    try:
        return int(stripped)
    except ValueError:
        pass
    try:
        return float(stripped)
    except ValueError:
        pass
    if (stripped.startswith('"') and stripped.endswith('"')) or \
       (stripped.startswith("'") and stripped.endswith("'")):
        return stripped[1:-1]
    return stripped


def read_kv_config(path: Union[str, Path], encoding: str = "utf-8") -> Dict[str, Any]:
    """Parse a key=value configuration file with comments and type coercion.

    Args:
        path: Path to the config file.
        encoding: Character encoding for the file.

    Returns:
        A dict with coerced values (int, float, bool, or stripped string).

    Examples:
        >>> read_kv_config("empty.cfg") == {}
        True
    """
    out: Dict[str, Any] = {}
    p = Path(path)
    if not p.exists():
        return out
    with p.open("r", encoding=encoding) as f:
        for lineno, raw in enumerate(f, start=1):
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if "=" not in line:
                raise ValueError(f"line {lineno}: expected '=' separator")
            key, _, value = line.partition("=")
            key = key.strip()
            if not key:
                raise ValueError(f"line {lineno}: empty key")
            out[key] = _coerce(value)
    return out


def write_kv_config(path: Union[str, Path], data: Dict[str, Any], encoding: str = "utf-8") -> int:
    """Write a dict as key=value lines; return the number of entries written.

    Args:
        path: Destination path.
        data: Mapping of keys to values.
        encoding: Character encoding.

    Returns:
        The number of entries serialized.

    Examples:
        >>> write_kv_config("out.cfg", {}) == 0
        True
    """
    p = Path(path)
    if p.parent and not p.parent.exists():
        p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("w", encoding=encoding) as f:
        for k in sorted(data):
            f.write(f"{k}={data[k]}\n")
    return len(data)

from pathlib import Path
from typing import Union, List

def delete_empty_dirs(root: Union[str, Path]) -> int:
    """Recursively delete empty directories under 'root'.

    Args:
        root: Root directory to scan.

    Returns:
        Number of empty directories removed.

    Examples:
        >>> delete_empty_dirs("/tmp/empty_demo_dir") >= 0
        True
    """
    base = Path(root)
    if not base.is_dir():
        return 0
    removed: List[Path] = []
    for p in sorted(base.rglob("*"), reverse=True):
        if p.is_dir():
            try:
                next(p.iterdir())
            except StopIteration:
                try:
                    p.rmdir()
                    removed.append(p)
                except OSError:
                    pass
            except OSError:
                continue
    try:
        next(base.iterdir())
    except StopIteration:
        try:
            base.rmdir()
            removed.append(base)
        except OSError:
            pass
    except OSError:
        pass
    return len(removed)

from pathlib import Path
from typing import Union, List, Set, Tuple

def safe_walk(root: Union[str, Path], max_links: int = 1000) -> List[Path]:
    """Walk a directory, stopping any symlink chain longer than max_links.

    Args:
        root: Root directory to walk.
        max_links: Maximum number of symlink hops to follow.

    Returns:
        A list of visited regular file Paths; cycles halt further descent.

    Examples:
        >>> isinstance(safe_walk("/tmp/empty_demo_dir"), list)
        True
    """
    base = Path(root)
    if not base.is_dir():
        raise NotADirectoryError(str(base))
    visited_inodes: Set[Tuple[int, int]] = set()
    out: List[Path] = []

    def descend(p: Path, depth: int) -> None:
        try:
            st = p.stat()
        except OSError:
            return
        key: Tuple[int, int] = (st.st_dev, st.st_ino)
        if key in visited_inodes:
            return
        visited_inodes.add(key)
        if p.is_file():
            out.append(p)
            return
        if not p.is_dir():
            return
        if depth >= max_links:
            return
        try:
            children = list(p.iterdir())
        except OSError:
            return
        for child in children:
            descend(child, depth + 1)

    descend(base, 0)
    return sorted(out)

import functools
from pathlib import Path
from typing import Callable, Any

def rotate_output(max_bytes: int = 10 * 1024 * 1024, backups: int = 3) -> Callable[..., Any]:
    """Decorator that rotates the output file when it grows beyond 'max_bytes'.

    Args:
        max_bytes: Threshold for rotation in bytes.
        backups: Number of previous versions to retain on disk.

    Returns:
        A decorator that wraps a function with rotation behavior.

    Examples:
        >>> @rotate_output(max_bytes=10, backups=1)
        ... def append_line(p, t): Path(p).write_text(t)
        >>> callable(append_line)
        True
    """
    if max_bytes <= 0:
        raise ValueError("max_bytes must be > 0")
    if backups < 0:
        raise ValueError("backups must be >= 0")

    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(path: Any, *args: Any, **kwargs: Any) -> Any:
            p = Path(path)
            if p.exists() and p.stat().st_size > max_bytes:
                for i in range(backups, 0, -1):
                    older = p.with_suffix(p.suffix + f".{i}")
                    newer = p.with_suffix(p.suffix + f".{i - 1}")
                    if older.exists():
                        older.unlink()
                    if newer.exists():
                        newer.rename(older)
                if p.exists():
                    p.rename(p.with_suffix(p.suffix + ".0"))
            return func(path, *args, **kwargs)
        return wrapper
    return decorator
